import { PayoutBatchTable, type PayoutBatchTableRow } from './payout-batch-table';
import { AdminTablePaginationFooter, AdminTableScroll } from '../../components/admin-data-table';
import { AdminFilterChipGroup } from '../../components/admin-filter-chip-group';
import {
  AdminFormControlButton,
  AdminFormInput,
  AdminFormTextarea,
} from '../../components/admin-form-controls';
import { AdminActionsForm } from '../../components/admin-inline-action-form';
import { AdminInlineNotice } from '../../components/admin-inline-notice';
import { AdminTraceSummary } from '../../components/admin-overview-card';
import { AdminSectionHeader } from '../../components/admin-page-template';
import { AdminTablePanel } from '../../components/admin-table-panel';
import { MoneyText } from '../../components/money-text';
import { StatusBadge, StatusBadgeLink } from '../../components/status-badge';
import type { PayoutServerPagination } from './payouts-page-model';

type FormAction = (formData: FormData) => void | Promise<void>;

type PayoutBatchListSectionProps = {
  readonly pagination: PayoutServerPagination<PayoutBatchTableRow>;
  readonly paginationHrefForPage: (page: number) => string;
  readonly rows: readonly PayoutBatchTableRow[];
  readonly selectedRow?: PayoutBatchTableRow | null;
  readonly selectionClearHref?: string;
  readonly showOperatorEvidence?: boolean;
  readonly updateTransferRefAction: FormAction;
};

export function PayoutBatchListSection({
  pagination,
  paginationHrefForPage,
  rows,
  selectedRow = null,
  selectionClearHref = '/payouts',
  showOperatorEvidence = false,
  updateTransferRefAction,
}: PayoutBatchListSectionProps) {
  return (
    <AdminTablePanel
      description="Partner settlement batches ordered so unresolved money movement stays at the top."
      resultLabel={`${pagination.totalRows} row(s)`}
      resultTone={pagination.totalRows > 0 ? 'info' : 'warning'}
      title="Payout batch list"
    >
      <AdminFilterChipGroup ariaLabel="Payout batch toolbar" className="admin-mb-12">
        <StatusBadge tone="success">Newest active first</StatusBadge>
        <StatusBadge tone="info">Payout record</StatusBadge>
        <StatusBadge tone="warning">Reconciliation</StatusBadge>
        <StatusBadgeLink href="/earnings" tone="neutral">
          Review earnings
        </StatusBadgeLink>
      </AdminFilterChipGroup>

      {selectedRow ? (
        <section aria-labelledby="selected-payout-transfer-title" className="admin-mb-16">
          <AdminSectionHeader
            actions={
              <StatusBadgeLink href={selectionClearHref} tone="neutral">
                Close editor
              </StatusBadgeLink>
            }
            description="Confirm the fixed target, account, amount, and risk before changing bank evidence."
            title="Selected payout transfer"
            titleId="selected-payout-transfer-title"
          />
          <AdminTraceSummary
            ariaLabel="Selected payout transfer summary"
            inferScope={false}
            metrics={[
              {
                detail: selectedRow.shortId,
                label: 'Target',
                value: selectedRow.partnerLabel,
              },
              {
                detail: selectedRow.currency,
                label: 'Amount',
                value: <MoneyText amount={selectedRow.totalAmount} currency={selectedRow.currency} />,
              },
              {
                detail: selectedRow.bankAccountDetail ?? 'No approved payout account is available.',
                label: 'Bank account',
                value: selectedRow.bankAccountLabel ?? 'Missing',
              },
              {
                detail: selectedRow.riskDetail ?? selectedRow.readinessSummary,
                label: 'Risk',
                value: selectedRow.riskLabel ?? 'Review',
              },
              {
                detail: selectedRow.notes || 'No transfer note.',
                label: 'Current reference',
                value: selectedRow.transferRef || 'Not recorded',
              },
            ]}
          />
          <AdminActionsForm action={updateTransferRefAction} className="admin-form-grid admin-mt-12">
            <input name="payoutBatchId" type="hidden" value={selectedRow.id} />
            <input name="expectedStatus" type="hidden" value={selectedRow.rawStatus ?? selectedRow.statusLabel} />
            <input name="expectedTransferRef" type="hidden" value={selectedRow.transferRef} />
            <input name="expectedNotes" type="hidden" value={selectedRow.notes} />
            <AdminFormInput
              defaultValue={selectedRow.transferRef}
              label="Transfer reference"
              labelVisibility="visible"
              maxLength={120}
              name="transferRef"
              placeholder="Bank transfer reference"
            />
            <AdminFormTextarea
              defaultValue={selectedRow.notes}
              label="Transfer note"
              labelVisibility="visible"
              maxLength={500}
              name="notes"
              placeholder="Transfer evidence note"
              rows={3}
            />
            <AdminFormTextarea
              label="Change reason"
              labelVisibility="visible"
              maxLength={1000}
              minLength={10}
              name="reason"
              placeholder="Why this transfer evidence is changing"
              required
              rows={3}
            />
            <AdminFormInput
              autoComplete="off"
              label={`Reconfirm batch ID: ${selectedRow.id}`}
              labelVisibility="visible"
              maxLength={128}
              name="confirmationPayoutBatchId"
              placeholder={selectedRow.id}
              required
            />
            <AdminFormControlButton className="button-primary" type="submit">
              Save transfer evidence
            </AdminFormControlButton>
          </AdminActionsForm>
        </section>
      ) : (
        <AdminInlineNotice className="admin-mb-16" tone="info">
          Choose Review transfer on one payout batch to edit its bank reference and note.
        </AdminInlineNotice>
      )}

      <AdminTableScroll>
        <PayoutBatchTable
          rows={rows}
          showOperatorEvidence={showOperatorEvidence}
        />
      </AdminTableScroll>
      <AdminTablePaginationFooter
        activePage={pagination.page}
        ariaLabel="Payout batch pages"
        from={pagination.from}
        hrefForPage={paginationHrefForPage}
        to={pagination.to}
        totalPages={pagination.totalPages}
        totalRows={pagination.totalRows}
      />
    </AdminTablePanel>
  );
}
